1	export type Item = {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	};
7	export type Step = { op: string; items?: Item[] };
8	export type Scenario = { customer: { yearsWithMHPCO: number }; steps: Step[] };
9	
10	export type StepResult = { premium: number };
11	export type ScenarioResult = { results: StepResult[] };
12	
13	const BASE_PREMIUMS: Record<string, number> = {
14	  sword: 100,
15	  amulet: 60,
16	  staff: 80,
17	  potion: 40,
18	  rune: 25,
19	  moonstone: 25,
20	};
21	
22	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
23	const PROCESSING_FEE = 5;
24	
25	const CURSE_SURCHARGE_RATE = 0.5;
26	
27	const BLOCK_SIZE = 3;
28	const BLOCK_BASE_PREMIUM = 60;
29	
30	const countByType = (items: Item[]): Map<string, number> => {
31	  const counts = new Map<string, number>();
32	  for (const item of items) {
33	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
34	  }
35	  return counts;
36	};
37	
38	const basePremiumForType = (type: string, count: number): number =>
39	  count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * BASE_PREMIUMS[type];
40	
41	const policyBasePremium = (items: Item[]): number =>
42	  [...countByType(items)]
43	    .map(([type, count]) => basePremiumForType(type, count))
44	    .reduce((total, premium) => total + premium, 0);
45	
46	const itemModifierSurcharges = (items: Item[]): number =>
47	  items.reduce(
48	    (total, item) =>
49	      total + (item.cursed ? BASE_PREMIUMS[item.type] * CURSE_SURCHARGE_RATE : 0),
50	    0,
51	  );
52	
53	const quotePremium = (items: Item[] = []): number => {
54	  const policyBase = policyBasePremium(items);
55	  const itemSurcharges = itemModifierSurcharges(items);
56	  const firstInsuranceSurcharge = policyBase * FIRST_INSURANCE_SURCHARGE_RATE;
57	  return Math.ceil(
58	    policyBase + itemSurcharges + firstInsuranceSurcharge + PROCESSING_FEE,
59	  );
60	};
61	
62	export const runScenario = (scenario: Scenario): ScenarioResult => ({
63	  results: scenario.steps.map((step) => ({
64	    premium: quotePremium(step.items),
65	  })),
66	});
